export const allSuitPowers=Object.values(suitPowers).flat();
export function normalizeSuit(raw={}){return {overlay:allSuitPowers.some(p=>p.id===raw?.overlay)?raw.overlay:null,records:[...new Set((Array.isArray(raw?.records)?raw.records:[]).filter(id=>allSuitPowers.some(p=>p.id===id)))]};}
export function suitPowerFor(name,id){return (suitPowers[name]||[]).find(p=>p.id===id)||null;}
export function suitSubject(power,o){if(!o||['portal','home','diglevel','digtools','crew','workshop'].includes(o.kind))return false;if(power.kind==='all')return true;const living=o.life||o.id==='plant'||/^farm-(garden|orchard|leaf|biodome|hydro|vertical|robot|water)/.test(o.id)||/^cave-(life|pigment|echo)/.test(o.id);return !!(living||power.kind==='environment'&&/water|habitat|cleanup|plant|soil/.test(o.id));}
export function activateSuit(raw,name,id){const s=normalizeSuit(raw);if(!suitPowerFor(name,id))return s;s.overlay=id;if(!s.records.includes(id))s.records.push(id);return s;}
export function suitPowerView(name,id,step=0,context={}){const power=suitPowerFor(name,id);if(!power)return null;const n=Number.isInteger(step)?((step%3)+3)%3:0,o=objects.find(o=>o.id===context.target&&o.zone===context.zone),pos=context.position||[200,500],distance=o?Math.hypot(o.x-pos[0],o.y-pos[1]):null,angle=o?Math.atan2(-(o.y-pos[1]),o.x-pos[0])*180/Math.PI:null;let text=power.steps[n][1];if(o)text='Selected place: '+o.name+'. '+text;if(id==='measure-map'&&o)text+=' Straight line: '+Math.round(distance)+' training units. Direction: '+Math.round(angle)+'° from map right (positive is up).';if(id==='environmental-survey'&&context.farm)text+=' Current greenhouse model: shade '+(context.farm.shade?'on':'off')+', vent '+(context.farm.vent?'open':'closed')+'.';if(id==='adaptation-scan'&&o?.life==='dolphin')text+=' This dolphin is a mammal and breathes air.';if(id==='adaptation-scan'&&o?.life==='shark')text+=' This shark is a fish and uses gills.';return {id,title:power.name,heading:power.steps[n][0],text,step:n,art:power.art+'-'+n,target:o?.id||null,travel:id==='geometry-builder'?'yard-build':id==='restoration-planner'?'farm-biodome':id==='environmental-survey'?'farm-biodome':null};}
export function suitArt(key){if(key.startsWith('adaptation-'))return aquaticArt(['life-shark','life-dolphin','life-angler'][Number(key.slice(-1))]||'life-shark');if(!key.startsWith('measure')&&!key.startsWith('geometry'))return pipToolArt(key);const n=Number(key.slice(-1));let shapes='';if(key.startsWith('measure')){for(let x=20;x<=300;x+=40)shapes+=`<path d="M${x} 15v150"/>`;for(let y=25;y<=165;y+=40)shapes+=`<path d="M20 ${y}h280"/>`;shapes+='<path d="M40 145L260 45" stroke="#8653b6" stroke-width="7"/><circle cx="40" cy="145" r="8" fill="#d96b24"/><circle cx="260" cy="45" r="8" fill="#60b3cf"/>';if(n>0)shapes+='<path d="M40 145h220V45" stroke="#d96b24" stroke-width="5" fill="none"/>';if(n===2)shapes+='<path d="M80 145a40 40 0 0 0-4-16" stroke="#39864a" stroke-width="5" fill="none"/>';}else{shapes='<path d="M20 145h70v-40h140v40h70" stroke="#aa8562" stroke-width="9" fill="none"/><path d="M80 105h160" stroke="#8653b6" stroke-width="12"/>';if(n>0)shapes+='<path d="M90 100l35-60 35 60 35-60 35 60" stroke="#60b3cf" stroke-width="6" fill="none"/>';if(n===2)shapes+='<path d="M115 155v-35a45 45 0 0 1 90 0v35z" fill="#c7e5aa"/>';}return '<svg xmlns="http://www.w3.org/2000/svg" width="320" height="180"><rect width="320" height="180" rx="18" fill="#e9f1e7"/><g stroke="#72929b" stroke-width="1">'+shapes+'</g></svg>';}
export const suitArtKeys=[...new Set(allSuitPowers.flatMap(p=>[0,1,2].map(n=>p.art+'-'+n)))];
export function suitOverlayPoints(power,zone,habitat='lake',level=0){return objects.filter(o=>o.zone===zone&&(zone!=='dig'||o.level===level)&&(!o.habitat||o.habitat===habitat)&&suitSubject(power,o)).slice(0,12);}
export function suitOverlay(power,zone,habitat='lake',level=0){const points=suitOverlayPoints(power,zone,habitat,level);let shapes='';if(power.id==='measure-map'){for(let x=20;x<1000;x+=40)shapes+=`<path d="M${x} 100v420"/>`;for(let y=100;y<520;y+=40)shapes+=`<path d="M20 ${y}h960"/>`;}for(const o of points)shapes+=`<circle data-suit-target="${o.id}" cx="${o.x}" cy="${o.y}" r="48" stroke-width="5"/>`;if(['connection-vision','restoration-planner','geometry-builder'].includes(power.id))for(let i=1;i<points.length;i++)shapes+=`<path d="M${points[i-1].x} ${points[i-1].y}L${points[i].x} ${points[i].y}" stroke-width="4" stroke-dasharray="10 8"/>`;return '<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="600"><g stroke="#ac72df" opacity=".8" fill="none" stroke-width="1">'+shapes+'</g></svg>';}
